// Semantic teaching model, independent of the participant-diagram renderer.
const person='ex:Dana a schema:Person ;\n    schema:name "Dana" .';
const extension='ir:IncidentAssignment\n    rdfs:subClassOf schema:OrganizationRole .';
const assignment='ex:SOCAssignment a ir:IncidentAssignment ;\n    schema:member ex:Dana ;\n    schema:roleName "SOC analyst" ;\n    ir:forIncident ex:INC001 .';
const provenance='ex:PossibleExfiltration\n    prov:wasDerivedFrom ex:EDRAlert ;\n    prov:wasAttributedTo ex:Dana .';
const hierarchy='ir:EndpointIsolationAction\n    rdfs:subClassOf ir:ContainmentAction .\nir:ContainmentAction\n    rdfs:subClassOf ir:ResponseAction .\nir:ResponseAction\n    rdfs:subClassOf schema:Action .';
function participant(id,name,kind=''){return {id,name,kind};}
function message(from,to,label,title,body,operation,code='',result='',extra={}){return {from,to,label,title,body,operation,code,result,...extra};}
function readable(value){if(typeof value!=='string')return value;try{return JSON.parse(value);}catch{return value;}}
export function lessons(data,state={}){
 const r=data.results||{};
 const roles=r['07-public-roles']?.results||[];
 const dana=roles.find(row=>readable(row.name)==='Dana');
 const sample=dana?JSON.stringify(Object.fromEntries(Object.entries(dana).map(([k,v])=>[k,readable(v)])),null,2):'{"name":"Dana","role":"SOC analyst"}';
 const inferred=r.reasoning?.inferred_count??0;
 const loaded=r.load?.triples_loaded??0;
 const roleQuery=data.queries?.['07-public-roles.rq']||'';
 const typeQuery=data.queries?.['09-public-inference.rq']||'';
 const validationCase=state.validation||'valid';
 const wrong=validationCase==='wrongtype';
 const invented=validationCase==='invented';
 const proposal=invented?'ex:Dana ir:jobTitleLabel "SOC analyst" .':wrong?'ex:Dana a schema:Person ;\n    schema:name 42 .':person;
 const vocabReport=invented?r.vocab_invented:wrong?r.vocab_name_value:r.vocab_valid;
 const shapeReport=wrong?r.invalid_name_shapes:r.valid_shapes;
 const validateMessages=[message('agent','vocab','Check the predicate','Does this field belong to our vocabulary?','The vocabulary checker compares predicate and type IRIs with the declarations we loaded. This catches invented field names before an application accepts them.','onto_vocab_check',proposal,'The checker examines names, not whether a value is true.',{tone:'blue'}),message('vocab','app',invented?'Unknown field':'Declared field','Vocabulary checking returns a report',invented?'ir:jobTitleLabel was never declared in the loaded ontology. The example uses schema:roleName on an organization role instead.':wrong?'schema:name is a declared public predicate. A numeric value does not make that predicate undeclared; the value constraint is a separate question.':'The example uses declared predicates and classes from Schema.org, PROV-O and our extension.','onto_vocab_check → report',JSON.stringify({conforms:vocabReport?.conforms,hallucinated_terms:vocabReport?.hallucinated_terms||[]},null,2),invented?'conforms: false':'conforms: true',{reply:true,failed:invented})];
 if(!invented){validateMessages.push(message('agent','shacl','Check value constraints','Apply the application’s SHACL shape','Schema.org gives schema:name a shared meaning. Our application’s shape requires exactly one name with datatype xsd:string. These are different jobs.','onto_shacl','ex:PersonNameShape a sh:NodeShape ;\n    sh:targetClass schema:Person ;\n    sh:property [\n        sh:path schema:name ;\n        sh:minCount 1 ; sh:maxCount 1 ;\n        sh:datatype xsd:string\n    ] .','The shape is ours; it is not a universal Schema.org requirement.'),message('shacl','app',wrong?'Datatype violation':'Data conforms','SHACL checks the data against those rules',wrong?'The recorded native run identifies Dana and the schema:name path: 42 does not have datatype xsd:string.':'The recorded native run checked all selected focus nodes in the prepared example; no shape was unmatched.','onto_shacl → report',JSON.stringify({conforms:shapeReport?.conforms,focus_nodes:shapeReport?.focus_nodes,violation_count:shapeReport?.violation_count,...(wrong?{path:'https://schema.org/name',constraint:'datatype'}:{})},null,2),wrong?'Known predicate; invalid value for this shape.':'Conformance means the configured constraints passed.',{reply:true,failed:wrong}));}
 validateMessages.push(message('app','agent',invented||wrong?'Decline the proposal':'Accept checked facts','Your application owns the acceptance boundary','The library supplies validation reports. Your application decides whether to accept a proposed write and separately enforces identity, visibility and tool permissions.','Application decision',invented||wrong?'if (!report.conforms) {\n  return rejectProposal(report);\n}':'if (vocab.conforms && shapes.conforms) {\n  return acceptTrustedProposal();\n}','This final handoff is an illustrated integration pattern, not a write performed by this page.',{reply:true,failed:invented||wrong}));
 const reasoned=!!state.reasoned;
 const reasonMessages=[message('app','oo','Load definitions + facts','The stored facts do not include every consequence','The ontology supplies the type hierarchy, including our extension of schema:Action. The instance data says which specific kind of action IsolateLaptop is.','onto_load',hierarchy+'\n\nex:IsolateLaptop a ir:EndpointIsolationAction .',`${loaded} asserted triples in the combined fixture.`)];
 if(reasoned)reasonMessages.push(message('app','oo','Apply RDFS reasoning','Replay the recorded reasoning operation','The reasoner follows subclass and subproperty statements to a fixpoint. The selected RDFS profile materializes the resulting triples in the store.','onto_reason','open-ontologies reason --profile rdfs\n    --certificate output/certificate',`${inferred} additional relationships derived in the native run.`,{tone:'violet'}));
 reasonMessages.push(message('agent','oo','ASK about schema:Action','Ask a question using the public type','The querying agent does not need to name EndpointIsolationAction. It can ask whether the specific instance belongs to the broader public schema:Action type.','onto_query',typeQuery,'The query is evaluated against the prepared store.'));
 reasonMessages.push(message('oo','agent',reasoned?'true · derived type':'false · not stored yet',reasoned?'The public-type query now matches':'Absence from the store is not a logical negation',reasoned?'The class hierarchy yields IsolateLaptop rdf:type schema:Action. This is a consequence of the supplied definitions, not a claim about whether the action is safe or approved.':'Before materialization this ASK returned false because that type triple was absent from the queried store. The definitions can still entail it under RDFS.','onto_query → ASK result',JSON.stringify(reasoned?r['09-public-inference']:r.public_before_reasoning,null,2),reasoned?'Derived: ex:IsolateLaptop a schema:Action .':'Use “Replay reasoning” above to see the later result.',{reply:true,tone:'violet'}));
 const plan=r.change_plan||{};const changes=plan.conservativity?.new_consequences_over_old_signature||[];
 const inferredChange=changes.find(c=>c.warrant==='engine_opinion');
 return [
 {id:'concepts',tab:'Concepts',kicker:'01 / DEFINITIONS, FACTS, ENGINE',title:'Keep definitions and facts separate.',description:'Follow the model from a reusable definition to a particular instance and a queryable answer.',mode:'Teaching sequence · native load and query outputs recorded',takeTitle:'Open Ontologies operates on explicit meaning.',take:'An ontology defines classes and relationships. An instance graph supplies concrete facts. The Open Ontologies engine loads, queries, validates and reasons over them.',participants:[participant('you','You','MODEL AUTHOR'),participant('model','Your RDF model','DEFINITIONS + FACTS'),participant('oo','Open Ontologies','ENGINE'),participant('agent','AI agent','CONSUMER')],messages:[
  message('you','model','Define a relationship','A class describes a kind of thing','We extend an existing public role class with an incident-specific assignment. This definition is reusable across many people and many incidents.','Design the ontology',extension,'ir: is our namespace. schema: is Schema.org.',{source:'https://schema.org/OrganizationRole'}),
  message('you','model','Add particular instances','Facts refer to concrete IDs','Dana is a particular person. SOCAssignment is a particular role assignment. The definitions and these instance facts are stored as RDF triples.','Write RDF instance data',person+'\n\n'+assignment,'A triple has a subject, a predicate and an object.'),
  message('model','oo','Load local RDF','The engine reads the model','We load a locally pinned subset of public definitions together with our extension and fictional facts. A prefix alone would not fetch those definitions.','onto_load','open-ontologies load incident.ttl',`${loaded} asserted triples loaded in the native run.`),
  message('agent','oo','Query linked facts','An agent can ask a precise question','After preparing the example store with reasoning, an agent uses public role properties plus our incident scope to retrieve people and their assignments.','onto_query',roleQuery,'The stored facts have stable IDs and explicit relationships.'),
  message('oo','agent','Return structured rows','The answer comes from graph matches','The recorded query returns nine people-and-role rows. This is one readable projection of a returned row, rather than a generated paragraph.','onto_query → SELECT rows',sample,'The application can follow these IDs to other facts.',{reply:true}),
 ]},
 {id:'reuse',tab:'Public terms',kicker:'02 / COMPOSE PUBLIC VOCABULARIES',title:'Reuse shared terms. Add local scope.',description:'Choose public definitions at design time, then keep the selected vocabulary snapshot with your model.',mode:'Design-time participants · local runtime copies',takeTitle:'Reuse vocabulary IRIs; make your extensions explicit.',take:'schema:Person, schema:OrganizationRole and schema:Action come from Schema.org. PROV-O supplies provenance terms. Incident-specific classes and relations live under ir:.',participants:[participant('you','You','MODEL AUTHOR'),participant('schema','Schema.org','PUBLIC VOCABULARY'),participant('prov','W3C PROV-O','PUBLIC ONTOLOGY'),participant('model','Your RDF model','COMPOSED MODEL')],messages:[
  message('you','schema','Choose common terms','Borrow the existing people-and-action vocabulary','The example uses actual Schema.org IRIs for Person, Organization, OrganizationRole, Action, name, member and roleName. These are not renamed local duplicates.','Choose public vocabulary',person,'Public term: https://schema.org/Person',{source:'https://schema.org/Person'}),
  message('schema','model','Reuse qualified roles','A role can qualify a membership relationship','Schema.org documents an intermediate OrganizationRole: the organization’s member is a role, and the role’s member is a person. The example uses that pattern for SOC and IT assignments.','Schema.org OrganizationRole','ex:SOC schema:member ex:SOCAssignment .\nex:SOCAssignment schema:member ex:Dana ;\n    schema:roleName "SOC analyst" .','A role is a relationship object with its own properties.',{reply:true,source:'https://schema.org/OrganizationRole'}),
  message('you','prov','Choose provenance terms','Record what a claim was derived from','PROV-O supplies Entity, wasDerivedFrom and wasAttributedTo. We retain a local “supportedBy” relation as a more specific subproperty of prov:wasDerivedFrom.','W3C PROV-O',provenance,'The provenance link describes the recorded claim; it does not establish that the claim is true.',{source:'https://www.w3.org/TR/prov-o/'}),
  message('you','model','Add incident scope','Extend the shared model for this domain','Schema.org does not supply this lab’s incident-scoped assignment and approval rules. We add those definitions in our own namespace instead of pretending they are public terms.','Local extension',extension+'\n\nir:forIncident a owl:ObjectProperty ;\n    rdfs:range ir:SecurityIncident .','Local type → public parent; local relation → local context.'),
  message('you','model','Pin local definitions','Keep the actual definitions with your data','The download contains 72 selected RDF statements extracted from the official Schema.org and PROV-O vocabulary files, with retrieval URLs and SHA-256 digests. Runtime operations load that snapshot; the diagrams do not imply a live call to vocabulary websites.','public-vocabulary.ttl','@prefix schema: <https://schema.org/> .\n@prefix prov: <http://www.w3.org/ns/prov#> .\n\n# Declarations and relevant hierarchy\n# are included in the local snapshot.','A namespace prefix abbreviates an IRI. It is not an import.'),
 ]},
 {id:'query',tab:'Query',kicker:'03 / FROM TEXT TO GRAPH ANSWERS',title:'Query linked facts with shared terms.',description:'See the boundary between extraction, RDF storage and a deterministic SPARQL query.',mode:'Extraction illustrated · SPARQL results recorded from the native engine',takeTitle:'The LLM can propose facts; SPARQL matches accepted facts.',take:'Open Ontologies does not turn every claim into truth. A trusted application accepts data, and agents can retrieve structured answers from the resulting graph.',participants:[participant('source','Source message','INPUT'),participant('extractor','SOC agent','PROPOSES RDF'),participant('oo','Open Ontologies','RDF + SPARQL'),participant('consumer','IT agent','QUERIES FACTS')],messages:[
  message('source','extractor','Supply source text','Extraction is one possible upstream step','A message can be converted into candidate RDF. This exchange illustrates a possible agent integration; no LLM extraction was executed by this website.','Illustrated extraction','"Dana is the SOC analyst assigned to INC-001."','Keep the source message ID and time with extracted data.'),
  message('extractor','oo','Propose typed RDF','Use declared public and local terms','The candidate data uses schema:member and schema:roleName, plus ir:forIncident. In a real integration, validate it and let a trusted application accept it before it becomes shared state.','onto_load after application checks',assignment,'The prepared fixture was loaded separately for the recorded run.'),
  message('consumer','oo','SELECT the relationship','A query specifies the pattern to match','This query follows an OrganizationRole to its member and roleName, scoped by our local incident relation. It does not require every consumer to invent its own meaning for “assigned to.”','onto_query',roleQuery,'The prepared, materialized example uses public role types.'),
  message('oo','consumer','Return matched values','Inspect the values that actually matched','The native query returns nine rows. One shown here links Dana to the role name. A separate PROV-O query also returns the source and author of a finding.','onto_query → rows',sample,'Provenance query: source synthetic-edr-007; author Dana; finding status Suspected.',{reply:true}),
 ]},
 {id:'validate',tab:'Validate',kicker:'04 / VOCABULARY CHECK + SHACL',title:'Validate the field names and values.',description:'Try a valid proposal, an invented predicate, and a value that violates our application shape.',mode:'Recorded checker and SHACL outputs · application handoff illustrated',takeTitle:'Public vocabulary and application constraints do different jobs.',take:'Schema.org supplies shared terms. Vocabulary checking catches undeclared names. SHACL checks configured data constraints. The application decides what gets accepted.',participants:[participant('agent','AI agent','PROPOSES DATA'),participant('vocab','Vocabulary check','OPEN ONTOLOGIES'),participant('shacl','SHACL validator','OPEN ONTOLOGIES'),participant('app','Your application','ACCEPTANCE BOUNDARY')],messages:validateMessages},
 {id:'reason',tab:'Reason',kicker:'05 / DERIVE A PUBLIC TYPE',title:'Derive a type nobody directly asserted.',description:'Compare the same public-type query before and after recorded RDFS materialization.',mode:'Replay of a recorded native RDFS run',takeTitle:'Reasoning follows the definitions you supplied.',take:'A local EndpointIsolationAction inherits through ContainmentAction and ResponseAction to schema:Action. This makes a generic public-type query useful to another agent.',participants:[participant('app','Your application','LOAD + REASON'),participant('oo','Open Ontologies','STORE + REASONER'),participant('agent','AI agent','PUBLIC-TYPE QUERY')],messages:reasonMessages},
 {id:'plan',tab:'Plan changes',kicker:'06 / PREVIEW SEMANTIC CONSEQUENCES',title:'Inspect a model change before applying it.',description:'A deliberately wrong subclass edit shows why a semantic plan adds information beyond a text diff.',mode:'Recorded onto_plan result · no change applied',takeTitle:'A syntactically valid definition can have unintended meaning.',take:'The plan found the one asserted edit plus a new inferred classification of PausePayroll. A reviewer still decides whether the new meaning is intended; no change was applied.',participants:[participant('you','You','PROPOSE A CHANGE'),participant('oo','Open Ontologies','SEMANTIC PLAN'),participant('reviewer','Reviewer','ASSESS INTENT'),participant('agent','AI agent','DOWNSTREAM CONSUMER')],messages:[
  message('you','oo','Plan one subclass edit','Propose a deliberately bad classification','For the lab, we wrongly classify ServicePauseAction as a kind of EndpointIsolationAction. The file parses, but that new definition changes which types the reasoner will derive.','onto_plan','ir:ServicePauseAction\n    rdfs:subClassOf ir:EndpointIsolationAction .\n\nopen-ontologies plan proposed.ttl','This is a teaching edit, not a recommended model.'),
  message('oo','oo','Compare old and new closure','Compute what the changed rules derive','The native plan compares consequences under its named OWL-RL rule table. It reports a change to the meaning of existing names, even though only one asserted triple was added.','onto_plan → conservativity analysis',JSON.stringify({insertions:plan.triple_delta?.insertions,rule_table:plan.conservativity?.rule_table,new_consequences:plan.conservativity?.new_consequences_total},null,2),'A reported rule-table comparison is narrower than a guarantee about every possible logic.'),
  message('oo','reviewer','Report a newly derived type','See what a downstream consumer would match', 'The plan exposes a new inferred type for the specific PausePayroll instance. That is the consequence a reviewer could miss in a one-line file diff.','onto_plan → consequence',inferredChange?inferredChange.triple.join('\n'):'ex:PausePayroll a ir:EndpointIsolationAction .','This finding is engine output. The independent proof checker did not start successfully.',{reply:true}),
  message('reviewer','you','Review the intended meaning','The tool cannot choose sensible definitions for you','A reviewer can reject this classification because it conflates distinct actions. The library makes the consequence inspectable; it does not establish the author’s intended meaning.','Human or application review','Decision for this lab: keep the original model.','The recorded plan did not apply the proposal.',{reply:true}),
  message('oo','agent','Preserve the current model','Planning and applying are separate operations','The agent continues to query the current accepted graph. A real workflow can apply an approved version later, then monitor or roll it back using the library’s lifecycle tools.','No apply performed','onto_plan   → inspect\nreview      → decide\nonto_apply  → only when approved','The last handoff illustrates the integration boundary; this page performs no writes.',{reply:true}),
 ]},
 ];
}
export function mermaidSource(lesson){
 const lines=['sequenceDiagram','    autonumber'];
 for(const p of lesson.participants)lines.push('    participant '+p.id+' as '+p.name);
 for(const m of lesson.messages)lines.push('    '+m.from+(m.reply?'-->>':'->>')+m.to+': '+m.label.replace(/[:\n]/g,' '));
 return lines.join('\n')+'\n';
}
